def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        # fill interior
        for y in range(y0 + 1, y1):
            for x in range(x0 + 1, x1):
                if out[y, x] == bg:
                    out[y, x] = 2
        emit(out, f"Fill the interior of the square at ({y0},{x0})-({y1},{x1}) with 2.")
        # find gap on border
        gap = None
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if (y in (y0, y1) or x in (x0, x1)) and g[y, x] == bg:
                    gap = (y, x)
        if gap is None:
            continue
        gy, gx = gap
        if gy == y0:
            d = (-1, 0)
        elif gy == y1:
            d = (1, 0)
        elif gx == x0:
            d = (0, -1)
        else:
            d = (0, 1)
        y, x = gy, gx
        while 0 <= y < H and 0 <= x < W and g[y, x] == bg:
            out[y, x] = 2
            y += d[0]
            x += d[1]
        emit(out, f"Shoot a ray of 2 from the gap at ({gy},{gx}) outward to the grid edge.")
    emit(out, "Final grid.")
    return out
